    if (this.mode === 'over') return;
    this.mode = 'over';
    this.overAt = this.time;
    this.fireHeld = false;
    this.controls.fire = false;
    this.shake = 0.9;
    this.callbacks.onGameOver?.({
      score: this.score,
      wave: Math.max(1, this.wave),
      kills: this.kills,
      weapon: this.weapon,
    });
