/* ============================================================
   VOX//ARENA — interface
   ============================================================ */

:root {
  --bg: #05070d;
  --bg-2: #080c15;
  --ink: #f3f7f1;
  --muted: #8794a1;
  --muted-2: #596675;
  --line: rgba(189, 220, 232, 0.15);
  --line-strong: rgba(189, 220, 232, 0.28);
  --acid: #d7ff45;
  --acid-soft: #a8df35;
  --cyan: #75f5ff;
  --ember: #ff6544;
  --danger: #ff4766;
  --weapon-accent: #d7ff45;
  --weapon-accent-rgb: 215, 255, 69;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --display: "Chakra Petch", "Arial Narrow", Impact, sans-serif;
  --body: "Inter", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  overscroll-behavior: none;
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
input:focus-visible {
  outline: 1px solid var(--acid);
  outline-offset: 4px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.is-hidden {
  display: none !important;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--bg);
  isolation: isolate;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background:
    radial-gradient(ellipse at 68% 42%, transparent 0 24%, rgba(2, 3, 7, 0.12) 55%, rgba(2, 3, 7, 0.74) 100%),
    linear-gradient(90deg, rgba(2, 4, 9, 0.47), transparent 40%, transparent 72%, rgba(2, 4, 9, 0.24));
}

.grain {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  opacity: 0.14;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");
}

---
.hud-bottom {
  position: absolute;
  inset: auto 0 0;
  padding: 0 calc(24px + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(24px + var(--safe-left));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
}

.weapon-card {
  --accent: var(--weapon-accent);
  width: clamp(255px, 27vw, 342px);
  padding: 14px 17px 13px;
  background:
    linear-gradient(105deg, rgba(8, 14, 20, 0.86), rgba(8, 14, 20, 0.48) 78%, rgba(8, 14, 20, 0.13)),
    linear-gradient(90deg, rgba(var(--weapon-accent-rgb), 0.08), transparent 50%);
  border-left: 2px solid var(--accent);
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 0 100%);
  backdrop-filter: blur(9px);
  transition: border-color 250ms ease;
}

.weapon-card.materialize {
  animation: card-materialize 600ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes card-materialize {
  0% { opacity: 0.25; transform: translateX(-8px); filter: brightness(2.4); }
  100% { opacity: 1; transform: translateX(0); filter: brightness(1); }
}

.weapon-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-family: var(--display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--muted-2);
}

.rarity {
  color: var(--accent);
}

.weapon-card h1 {
  margin: 7px 0 3px;
  font-family: var(--display);
  font-size: clamp(18px, 2.2vw, 28px);
  font-weight: 700;
  line-height: 0.98;
  letter-spacing: -0.015em;
  text-transform: uppercase;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 22px rgba(var(--weapon-accent-rgb), 0.16);
}

.weapon-meta {
  display: flex;
  gap: 6px;
  align-items: center;
  margin-bottom: 10px;
  font-family: var(--display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.13em;
  color: var(--muted);
}

.weapon-slash {
  color: var(--accent);
}

.stat-row {
  display: grid;
  grid-template-columns: 51px 1fr 26px;
  align-items: center;
  gap: 7px;
  height: 13px;
  font-family: var(--display);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.11em;
  color: var(--muted-2);
}

.stat-row b {
  font-weight: 500;
  text-align: right;
  color: var(--muted);
}

.stat-track {
  height: 3px;
  background: rgba(255, 255, 255, 0.07);
}

.stat-track i {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--accent);
  box-shadow: 0 0 7px rgba(var(--weapon-accent-rgb), 0.4);
  transition: width 400ms ease;
}

/* Transcript */
.transcript-wrap {
  position: absolute;
  left: 50%;
  bottom: calc(23px + var(--safe-bottom));
  transform: translateX(-50%);
  width: min(34vw, 460px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
}

.transcript {
  max-width: 100%;
  min-height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 4px 14px;
  border: 1px solid rgba(189, 220, 232, 0.12);
  background: rgba(5, 10, 15, 0.53);
  backdrop-filter: blur(7px);
  font-family: var(--display);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.035em;
  color: rgba(216, 228, 232, 0.7);
  clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 7px 100%, 0 calc(100% - 7px));
  transition: color 180ms ease, border-color 180ms ease;
}

